    "flashcards": [
      {
        "id": 1,
        "term": "Minuend",
        "category": "Mathematical Terminology",
        "definition": "The original number or quantity from which another number is to be subtracted.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Boxed Rule",
        "exact_textbook_quote": "In a subtraction problem: Minuend - Subtrahend = Difference.",
        "memory_trick": "Minuend is the 'Main' number at the top that gets diminished."
      },
      {
        "id": 2,
        "term": "Subtrahend",
        "category": "Mathematical Terminology",
        "definition": "The number or quantity being subtracted or taken away from the minuend.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Boxed Rule",
        "exact_textbook_quote": "The number being subtracted is called the subtrahend.",
        "memory_trick": "Subtrahend goes 'sub' (under) the minuend and does the subtracting."
      },
      {
        "id": 3,
        "term": "Difference",
        "category": "Mathematical Terminology",
        "definition": "The final quantitative result obtained by subtracting the subtrahend from the minuend.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Boxed Rule",
        "exact_textbook_quote": "The result of subtraction is called the difference.",
        "memory_trick": "Difference represents the remaining distance between two quantities."
      },
      {
        "id": 4,
        "term": "Borrowing (Regrouping)",
        "category": "Arithmetic Algorithm",
        "definition": "The mathematical process of taking one ten, hundred, or thousand from a higher place-value column when the top digit is smaller than the bottom digit.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Section 1",
        "exact_textbook_quote": "When the top digit is smaller than the bottom digit, borrow one from the next column to the left.",
        "memory_trick": "If you don't have enough in your house, borrow a 10 from your neighbor next door!"
      },
      {
        "id": 5,
        "term": "Borrowing Across Zeros",
        "category": "Arithmetic Algorithm",
        "definition": "Regrouping continuously across multiple zero digits by borrowing from the first non-zero column on the left, turning intermediate zeros into 9s, and adding 10 to the target column.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Section 1",
        "exact_textbook_quote": "When borrowing across zeros, intermediate zeros become 9s and the final target digit receives the 10.",
        "memory_trick": "Only the final house gets the full 10; every intermediate zero neighbor keeps a 9!"
      },
      {
        "id": 6,
        "term": "Checking Subtraction",
        "category": "Verification Protocol",
        "definition": "The verification method where the subtrahend and difference are added together to prove equality with the original minuend.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 3, Section 1",
        "exact_textbook_quote": "To check subtraction, add the subtrahend and the difference: Subtrahend + Difference = Minuend.",
        "memory_trick": "Bottom number plus Answer equals Top number!"
      },
      {
        "id": 7,
        "term": "Inverse Operation",
        "category": "Algebraic Principle",
        "definition": "Mathematical operations that reverse or undo each other, such as addition and subtraction.",
        "textbook_citation": "Arithmetic 5 Work-text, Page 4, Section 5",
        "exact_textbook_quote": "To find an unknown addend, use the inverse operation: subtract the known addend from the sum.",
        "memory_trick": "Inverse means opposite action: addition undoes subtraction, and subtraction undoes addition."
      },
      {
        "id": 8,
        "term": "Mental Carrying",
        "category": "Cognitive Technique",
        "definition": "The disciplined grade-5 skill of retaining carried and borrowed numbers mentally in working memory rather than scribbling helper marks on paper.",
        "textbook_citation": "Grade 5 Video Manual, Page 2; Lesson 2 Lecture",
        "exact_textbook_quote": "Fifth graders remember the carrying number in their head without writing marks over the problem.",
        "memory_trick": "Hold the digit in your mind's pocket to keep your work clean and automatic."
      }
    ],
